(window.YSKAR_TEXTE=window.YSKAR_TEXTE||{}).en={"nav.skip":"Skip to content","nav.main":"Main navigation","nav.menu":"Menu","nav.close":"Close","nav.lang":"Language","nav.tick":"Block","nav.tick.title":"The newest block. Open the live network page.","cta.join":"Take part","nav.g.part":"Take part","nav.g.know":"Understand","nav.g.join":"Join in","nav.start":"Where to begin","nav.start.d":"Five ways in, each with its first step","nav.mine":"Mine","nav.mine.d":"Find blocks with a phone, a PC or a graphics card","nav.wallet":"Wallet","nav.wallet.d":"Twelve words that only you hold","nav.node":"Run a node","nav.node.d":"Check every block yourself","nav.ysr":"YSR","nav.ysr.d":"21 million, every one of them mined","nav.chain":"The chain","nav.chain.d":"A blockchain of its own, and how it proves itself","nav.network":"Network, live","nav.network.d":"What the chain is doing right now","nav.explorer":"Explorer","nav.explorer.d":"Every block, every transfer, every address","nav.community":"Community","nav.community.d":"Where the project talks and decides","nav.build":"Build","nav.build.d":"Open code, a public API, proposals","nav.story":"Story and next steps","nav.story.d":"From block 0 to today, and what comes after","foot.claim":"Fair from block 0.","foot.sub":"YSKAR is a community project. No company stands behind it, and nobody has to be believed: every block can be checked.","foot.nav":"All pages","foot.whitepaper":"White paper","foot.find":"Find YSKAR","foot.imprint":"Legal notice","foot.privacy":"Privacy","foot.license":"Open source under the MIT License","title.home":"Fair from block 0","title.start":"Where to begin","title.mine":"Mining","title.wallet":"YSKAR Wallet","title.node":"Run a node","title.ysr":"YSR, the coin","title.chain":"The chain","title.network":"Network, live","title.explorer":"Explorer","title.build":"Build on YSKAR","title.community":"Community","title.story":"Story and next steps","ui.copied":"Copied","ui.copy":"Copy","ui.sample":"The screen shows sample data.","dawn.h":"It's still early here.","dawn.p":"Day <span data-live='day'></span>. The first light is only just coming up over this network. The people who shape it are the ones who are here now.","dawn.cta2":"Read the story so far","dawn.alt":"The same fjord at first light: a pale sky over snow-covered mountains and still water.","nav.guides":"Guides","nav.guides.d":"Every way to take part, step by step","nav.protocol":"Protocol","nav.protocol.d":"Coin, chain and wallets, byte by byte","nav.paper.d":"The system as it is implemented","title.guides":"Guides","title.protocol":"Protocol","title.paper":"White paper","title.imprint":"Legal notice","title.privacy":"Privacy","doc.toc":"On this page","foot.live":"The figures on these pages are read live from the public YSKAR API.","foot.stale":"The public YSKAR API is not answering right now. These pages show the chain as it stood on {date} (block {h}) and catch up on their own.","title.notfound":"Page not found","nf.h":"This page does not exist.","nf.p":"The link may be mistyped, or the page has moved. The chain itself is right where it was.","nf.home":"To the start page","nf.explorer":"Look something up in the explorer","home.hero.h1":"<span class=\"ln\"><span>Proof,</span></span> <span class=\"ln\"><span>not promise.</span></span>","home.hero.lead":"YSKAR is a currency with a blockchain of its own. Nothing was handed out in advance: every YSR is mined, and anyone can check every block. Fair from block 0.","home.hero.cta2":"See the chain so far","home.hero.live":"Day {d} · block {h} · {n} lights on the shore, one for each node that has reported in","home.hero.alt":"A dark fjord between snow-covered mountains under a starry sky. Ribbons of blue light move above it, and small warm lights glow on the far shore.","home.m1":"It did not start with a promise. It started with a block.","home.m2":"Nothing was mined in advance. Nothing was handed out. About 1.07 million YSR from the early days were burned to offset the head start.","home.m3":"Since then a new YSR comes into the world in one way only: a machine does the work, and anyone can check it.","walk.start.h":"<span data-live='day'></span> days, block by block.","walk.start.p":"Every light is a real block, and the gap between two lights is the time between them. Scroll to travel along the chain. Tap a light to open its block.","walk.c0.h":"It begins with one block.","walk.c0.p":"Its only message is “proof, not promise”. Its reward of 875 YSR went to an address nobody can spend from.","walk.c1.h":"Day one: 46 blocks.","walk.c1.p":"The first block after block 0 arrived at 18:03 UTC. By midnight there were 46 of them: the chain had found its rhythm.","walk.c3.h":"The head start is burned.","walk.c3.p":"1,066,101 YSR from the early days are sent to the address nobody can spend from, to offset the head start. It is all in this block.","walk.c4.h":"The community votes.","walk.c4.p":"Revision 6 is decided in the open: shared accounts, time locks, payments to a thousand recipients at once. Three rule upgrades were already live by then.","walk.c5.h":"You are here.","walk.c5.p":"The next block is about ten minutes away.","walk.c6.h":"Next: revision 6 switches on.","walk.c6.p":"In <span data-live='v6Left'></span> blocks. Every node knows the height in advance, so nothing changes by surprise.","walk.c6.h.past":"Revision 6 is live.","walk.c6.p.past":"Since block 10,000 the chain knows shared accounts, time locks and batch payments.","walk.c7.h":"Then the first era ends.","walk.c7.p":"Until block 12,000 every block creates 875 YSR, after that 437.5. Half of all YSR that will ever exist come from this first era.","walk.c7.h.past":"The first era is over.","walk.c7.p.past":"Since block 12,000 every block creates 437.5 YSR. The reward halves again every 12,000 blocks.","walk.open":"Open this block","walk.k.block":"Block {h} · {d}","walk.k.future":"Block {h} · still to come","home.walk.now":"Block {h} · day {d}","walk.hud.block":"Block {h}","walk.hud.ahead":"Block {h}","walk.hud.planned":"still to come · fixed in the code","walk.hud.day":"day {n}","walk.tip.block":"Block {h}","walk.tip.approx":"Details load in the explorer","walk.tip.solo":"Found by a single miner","walk.tip.pool":"Found by a pool","walk.tip.tx":"carried transfers","walk.legend.block":"a block","walk.legend.tx":"a block that carried transfers","walk.canvas":"The chain drawn as a ribbon of lights, one light for each block since block 0.","home.proof.h":"Don't take our word for it.","home.proof.p":"Every block carries its own proof. Your device can check it right now: no server, no account, only arithmetic.","prove.btn.genesis":"Check block 0 on this device","prove.btn.tip":"Check the newest block","prove.label":"Hash of the block header","prove.ok":"Valid. Block {h} was checked on this device in {ms} ms.","prove.bad":"Not valid: block {h} misses its target.","prove.open":"Open block {h} in the explorer","prove.note":"What your device just did: it ran the 136 bytes of the block header through SHA-256 twice. The result has to be smaller than the target the network set for that block. The zeros at the start show how small it is.","home.ways.h":"Three ways in.","home.ways.p":"The YSKAR mark is three ribbons that meet. So is the network: people who mine, people who hold and send, and people who keep a node running.","way.mine.h":"Lend it your machine.","way.mine.p":"A phone, a PC or a graphics card can find blocks. Alone, or in a pool that pays you inside the block itself and never holds your coins.","way.mine.cta":"How mining works","way.mine.alt":"A laptop on a wooden desk at night, running YSKAR Node Core; behind it a window onto a dark fjord.","way.wallet.h":"Twelve words. Yours alone.","way.wallet.p":"Your wallet lives on your own device. Nobody else holds your keys, including the people who build YSKAR.","way.wallet.cta":"Get the wallet","way.wallet.alt":"A phone with the YSKAR Wallet open, lying on a dark wooden desk next to a notebook with twelve handwritten lines, a pen and a cup of tea.","way.node.h":"Keep a light on.","way.node.p":"A node checks every block itself, from block 0. Each one makes the network harder to bend. A small computer on a windowsill is enough.","way.node.cta":"Run a node","way.node.alt":"A small computer with one cyan status light on a wooden windowsill; outside, a fjord at night with a few lights on the far shore.","home.ways.more":"Or build on it. The code is open, the API is public, and proposals are discussed where everyone can read them.","home.ways.more.cta":"For developers","home.early.say":"Day {d}. {n} nodes. {m} miners. {p} pools. {x} transfers. No listing. No price. This is what early looks like.","home.early.note":"Nodes and miners as they report themselves. All figures come from the public API.","home.early.p":"A small network, <span data-live='day'></span> days old. YSR is not listed anywhere and has no price; listings are in preparation, with no date and no names. What exists today is a chain that works, software you can run, and room for the people who show up now.","home.era.h":"Era <span data-live='era'></span>","home.era.p":"In this era every block creates <span data-live='rewardNow'></span> YSR. At block <span data-live='halvingHeight'></span> the reward halves, and again every 12,000 blocks after that. Half of all YSR that will ever exist come from the first 12,000 blocks. The schedule is written in the code; nobody can move it.","home.era.now":"Block <span data-live='height'></span>","home.era.left":"<span data-live='halvingLeft'></span> blocks to go","home.era.cta":"The whole schedule","home.people.h":"No company. Just people.","home.people.p":"YSKAR is a community project and belongs to the people who use it. They mine, run nodes, test releases and decide on changes in the open: revision 6 was put to a community vote.","home.people.cta":"Meet the community","home.people.cta2":"Open YSKAR Lab","home.people.alt":"About fifteen people seen from behind on a snowy shore at blue hour, each holding a small lantern, looking out over a fjord.","start.h1":"Pick your way in.","start.lead":"Taking part costs nothing. Start with whatever suits you; the same twelve words open every door later.","start.1.h":"I want to hold and send YSR","start.1.p":"Install the Android wallet, write twelve words on paper, show your address. That is all it takes to receive.","start.1.do":"To the wallet","start.2.h":"I want to mine","start.2.p":"Begin with the device you already have: Node Core on a PC, the Android app on a phone, the command line on a rig.","start.2.do":"To mining","start.3.h":"I want to check the chain myself","start.3.p":"Run a node. It verifies every block from block 0 and becomes one more light on the shore.","start.3.do":"Run a node","start.4.h":"I want to build or help","start.4.p":"Read the code, ask the public API, test a release, bring a proposal to YSKAR Lab.","start.4.do":"For developers","start.5.h":"I just want to watch for now","start.5.p":"Follow the chain live, open any block in the explorer, read along in the channel.","start.5.do":"The network, live","start.safe.h":"Three things to know first","start.alt.fjord":"A dark fjord under a starry sky.","mine.h1":"Lend it your machine.","mine.lead":"New YSR come from mining and from nowhere else. A phone, a PC or a graphics card can take part, alone or in a pool.","mine.cta":"Choose your setup","mine.cta2":"Try it right here","mine.try.h":"Mining is guessing, very fast.","mine.try.p":"Press start and this device joins in for a moment. It takes the newest block and searches for a number that makes its hash begin with enough zeros: the same search every miner runs, at practice difficulty.","mine.try.go":"Start guessing","mine.try.stop":"Stop","mine.try.again":"Once more","mine.try.tries":"Guesses","mine.try.speed":"Speed","mine.try.idle":"Nothing found yet. Every spark is a batch of guesses.","mine.try.found":"Found one after {n} guesses.","mine.try.none":"No luck in {n} guesses. That is mining too. Try again.","mine.try.real":"That was practice. The real network is {x} times harder: at {r}, this device alone would need about {t} for one real block. That is why miners join pools.","mine.try.canvas":"Sparks for each batch of guesses; a bright flash when a valid number is found.","mine.setup.h":"Choose your setup","mine.calc.h":"What could your machine find?","mine.pools.h":"The pools, live","wal.h1":"Twelve words. Yours alone.","wal.lead":"YSKAR Wallet is the Android app for YSR: send, receive, sign. Your key is created on your phone and stays there.","wal.cta2":"Install in four steps","wal.say":"Whoever has the twelve words has the funds. Write them on paper. Nobody from YSKAR will ever ask you for them.","node.h1":"Keep a light on.","node.lead":"A full node checks every block itself, from block 0, and passes it on. It asks nobody what is true. Every node that does this makes the network harder to bend.","node.cta":"Get Node Core","node.cta2":"From the command line","node.say":"Every light on this shore is a node that has reported in. Right now there are {n}. Yours would be number {k}.","node.core.h":"Node Core: node, wallet and miner in one window.","node.core.p":"Install it, and your computer verifies the chain on its own. Node Core also holds your wallet, mines with your processor or graphics card, can run a pool and signs messages. Version 1.1.0 for Windows 10 and 11 and for 64-bit Linux.","node.dl.win":"Windows installer","node.dl.deb":"Linux package (.deb)","node.dl.app":"Linux AppImage","node.dl.get":"Download","node.dl.all":"All files and checksums","node.dl.rel":"The release on GitHub","node.why.h":"What one more node changes","node.w1.p":"Your node recomputes the work, the signatures and every balance, starting at block 0. A block that breaks a rule is rejected, whoever sent it.","node.w2.h":"It carries the network","node.w2.p":"Every node passes blocks and transfers on to others. The more of them there are, in more places, the less the network depends on any single machine.","node.w3.h":"It needs little","node.w3.p":"From the command line a node runs on Linux, Windows and macOS, even on a Raspberry Pi. Node Core, the desktop app, runs on Windows and 64-bit Linux.","coin.h1":"21 million. Every one of them mined.","coin.lead":"YSR is the coin of the YSKAR chain. There will never be more than 21,000,000. Nothing was pre-mined or allocated: a new YSR exists for one reason only, a block was found.","coin.alt":"The YSR coin: a thick disc of blue glass with a raised rim and the YSKAR mark in relief.","coin.alt.flat":"The YSR coin: a dark disc with a blue ring and the YSKAR mark.","coin.bar.mined":"mined so far","coin.bar.burned":"of these burned or unspendable","coin.bar.open":"still to be mined","coin.eras.h":"The reward halves every 12,000 blocks.","coin.eras.p":"Each bar is one era and shows how many YSR it creates. The first era alone creates half of everything. The last new YSR appears in block 443,999; after that miners earn fees only.","coin.eras.era":"Era {n}","coin.eras.now":"now","coin.eras.rest":"Figures in YSR. 9+ stands for all later eras together.","coin.burn.h":"The head start was burned.","coin.burn.cta":"See it in block 3,974","chain.h1":"A chain of its own.","chain.lead":"YSKAR does not run on top of another network. It has its own blocks, its own peer-to-peer network and its own rules, and it proves every block with work that anyone can check.","chain.how.h":"One block, three steps.","chain.why.h":"Why an own chain matters","chain.y1.h":"Its rules are its own","chain.y1.p":"Fees, block times and upgrades are decided here, by the people who run YSKAR, and by nobody else's network.","chain.y2.h":"Nothing to take on trust","chain.y2.p":"Every block back to block 0 can be recomputed by anyone, with open software, on an ordinary computer.","chain.y3.h":"Changes arrive in the open","chain.y3.p":"A rule change is written into the code together with the block at which it starts. Every node knows it in advance. Revision 6 was put to a community vote.","chain.deep.h":"For the curious: how it works in detail","chain.deep.p":"From here on the page gets technical. Everything below comes from the consensus code and from the chain itself.","netp.lead":"What the chain is doing right now, read from the public API. Nothing here is estimated by hand.","bld.h1":"Build on it.","bld.lead":"All of YSKAR is open: node, wallets, miners, explorer and this website, under the MIT License. A public API answers without a key.","bld.cta":"Try the API","bld.cta2":"The code on GitHub","bld.1.h":"Read everything","bld.1.p":"The protocol is specified, the consensus code is short enough to read, and every figure on this site comes from that code or from the chain.","bld.2.h":"Ask the chain","bld.2.p":"Blocks, transfers, addresses, fees, pools and supply over plain HTTP. No key, no sign-up, open to any website.","bld.3.h":"Change it","bld.3.p":"Proposals go through YSKAR Lab, in public, from the first idea to the release. You sign in with your wallet.","comm.h1":"No company. Just people.","comm.lead":"YSKAR is a community project and belongs to the people who use it. This is where they talk, test and decide.","comm.ch.h":"Where to find everyone","comm.do.h":"What you can do. None of it needs permission.","comm.lab.h":"How a proposal becomes a release","comm.safe.h":"Stay safe","comm.ann":"Bitcointalk","story.h1":"Steps, not dates.","story.lead":"Where YSKAR comes from, what runs today and what comes next. Nobody here promises a delivery date: changes take effect at a block, not on a calendar day.","story.why.h":"Why YSKAR exists","story.why.say":"The goal is a currency people can use in everyday life. A solid foundation comes first. A short burst of hype is not the plan.","story.why.p":"YSKAR belongs to the people who use it. Your YSR sit at an address that only your twelve words open. Nobody has to be trusted: every block back to block 0 can be checked by anyone. New YSR come from mining, never from a promise.","story.run.h":"Running today","story.fix.h":"Fixed by block height","story.plan.h":"Planned, without a date","story.walk":"Walk along the chain from block 0","coin.field.alt":"A field of lights for all 21 million YSR: the ones mined so far are lit, the burned ones glow like embers, the rest is dark.","coin.field.burned":"burned","coin.f0.h":"21,000,000. Never more.","coin.f0.p":"Each light stands for <span data-field-unit></span> YSR, in the order they come into being. This is everything there will ever be.","coin.f1.p":"That many exist today, <span data-live='mintedPct'></span> of the total. Every one of them came out of a block that somebody found.","coin.f2.p":"About 1.07 million YSR from the early days were burned to offset the head start. They went to an address nobody can spend from and are gone for good.","coin.f3.h":"Half of everything comes first.","coin.f3.p":"The first 12,000 blocks create 10.5 million YSR: half of all there will ever be. The chain is at block <span data-live='height'></span>.","coin.f4.h":"Then it halves, again and again.","coin.f4.p":"Every 12,000 blocks the reward is cut in half. The last new YSR appears in block 443,999. After that, miners earn fees only.","coin.noprice.say":"YSR has no price today. It is not listed anywhere. What it has is a chain that anyone can check.","wal.phone.alt":"A phone showing real screens of the YSKAR Wallet, one after another.","wal.s1.h":"Your balance, and nothing in the way.","wal.s3.h":"One history for everything.","wal.s3.p":"Payments, block rewards and pool shares appear in one place. Amounts are exact to the 8th decimal place.","wal.s5.h":"Names instead of addresses.","wal.s5.p":"Save a contact once, and every payment with that person sits in a single thread.","pay.alt":"Many small lights flicker, gather into one bright point that becomes a block, and rays run from the block to every address it pays.","pay.0.h":"Everyone guesses at once.","pay.0.p":"Right now the whole network works at about <span data-live='hashrate'></span>: billions of numbers every second, all hunting for the same block.","pay.1.h":"One number fits.","pay.1.p":"About every ten minutes one machine finds a number that works. That is a new block, and the search starts again.","pay.2.h":"The block pays everyone who helped.","pay.2.p":"In a pool the reward is split by the work each miner delivered and paid inside the block itself. The newest pool block paid <span id='pay-n'></span> addresses at once.","pay.3.h":"No account. No payout threshold. No custody.","calcx.a":"My machine does","calcx.b":"and I mine","poolsx.last":"of the latest blocks","poolsx.fee":"fee","poolsx.seats":"seats taken","poolsx.rate":"reported","shore.on":"Switch one more on","shore.off":"Switch it off again","shore.note.on":"Number {k} is only lit on your screen. It counts once your node is running.","node.check.h":"From block 0 to today, without asking anyone.","comm.vote.say":"On 25 October 2026 the community voted on when revision 6 begins. It chose block 10,000.","comm.vote.cta":"What revision 6 brings","log.k":"Every block up to","log.cap":"Every row is one day since 9 September 2026 (UTC), every mark one block at its time of day. Warm marks carried transfers. Tap a mark to open the block.","log.cap.n":"Every row covers {d} days since 9 September 2026 (UTC), every mark is one block. Warm marks carried transfers. Tap a mark to open the block.","log.alt":"The logbook of the chain: every block since block 0 as a mark, one row per day.","comm.say":"Day {d}. {n} nodes keep the chain, {m} miners extend it, {p} pools share the work. Nobody was appointed. They showed up.","road.start.k":"25 Oct 2026","road.start":"The vote","road.end.k":"Block 10,000","road.end":"Revision 6 begins","road.now":"Block {h} · now","road.left":"{n} blocks to go. At the current pace that is {eta}.","road.done":"Revision 6 has been active since block 10,000.","road.need":"Nodes need a current release before that block.","road.need.done":"Nodes on an older release no longer follow the chain.","coin.turn":"Turn it over","coin.turn.back":"Turn it back","coin.back.k":"Block 0","coin.back.d":"9 September 2026","netp.say":"Block {h}, found {a}. {r} at work on the next one. {n} nodes are watching.","start.jump":"The five ways","start.guides":"Every way explained step by step","story.road.h":"The chain so far, and what is already set","story.road.p":"Seven marks along the chain. Those behind us carry their date. Those ahead carry only a block number, because that is all the code knows.","story.road.live":"See the latest blocks","miles.left":"in {n} blocks","forge.hash":"SHA-256, applied twice","forge.target":"must not exceed the target","forge.ok":"Valid: recomputed on this device.","forge.nodes":"{n} reporting nodes","forge.nodes.1":"1 reporting node","forge.paid":"{r} to {n} addresses","forge.paid.1":"{r} to one address","forge.before":"{n} blocks before it, spaced as they were found: {m} min","forge.alt":"The 136 bytes of the newest block header. The nonce changes until the hash falls below the target, then the nodes check it, and the block takes its place at the end of the chain and pays its reward.","term.note.live":"Answered by the public API on {d}.","term.note.snap":"The answer of {d}. The API is not answering right now; the page asks again on its own.","term.more":"Show all {n} lines","term.less":"Show fewer lines","term.alt":"A request to the public API and its answer","agol.sec":"{n} seconds ago","agol.sec.1":"a second ago","agol.min":"{n} minutes ago","agol.min.1":"a minute ago","agol.hours":"{n} hours ago","agol.hours.1":"an hour ago","agol.days":"{n} days ago","agol.days.1":"a day ago","netp.k":"Network, live","netp.k.snap":"Network on {date}","netp.say.snap":"Block {h} was the newest. {r} were at work on the next one. {n} nodes were watching.","netp.lead.snap":"The last state this page received. The public API is not answering right now; the page asks again on its own.","ex.h1":"Every block is public.","ex.lead":"Look up a block, a transfer or an address. Your browser recomputes the proof of work of every block it shows.","ex.q.ph":"Block, hash or address","pulse.tip.h":"The last {n} hours","pulse.next":"Block {h} is being mined. {t} since the last block.","pulse.around.h":"Around block {h}","pulse.around.n":"{n} blocks in these {k} hours","pulse.now":"now","pulse.by":"Found by {who}","pulse.alt":"Blocks on a time line. Each light is one block; the distance between two lights is the time between them.","ex.row.tx":"{n} transfers","ex.row.tx1":"1 transfer","ex.row.tx0":"no transfers","ex.proof.h":"The proof of work","ex.proof.p":"A miner turns two counters in the header, the nonce and the extranonce, until the hash of all 136 bytes falls below the target. Your browser has just repeated that calculation.","proof.pick":"Select a field to see what it holds.","pulse.around.1":"The only block in these {k} hours","ex.tx.batch":"Batch payment","ex.tx.script":"Script account spend","ex.txv.status":"Status","ex.txv.waiting":"Waiting for a block","ex.txv.sumPending":"Sent, but not in a block yet.","ex.txv.expected":"Expected in block {h}, in about {min} min, provided nothing with a higher fee arrives.","ex.txv.unknownWhen":"Further back in the queue than the forecast reaches.","ex.addr.waiting":"Waiting","ex.addr.older":"Load older activity","lv.an.apk.akku":"Some devices still close background apps to save battery. If mining stops on its own, set the app’s battery usage to “Unrestricted” (Settings → Apps → YSKAR Wallet → Battery).","lv.an.apk.dienst":"Since version 1.0.9 a dedicated service inside the app does the computing. Mining continues when you leave the app or lock the screen. While it runs, Android shows a notification with your hashrate; “Stop mining” ends it right there.","lv.an.apk.hintergrund":"Mining in the background","lv.an.apk.inst":"Installing","lv.an.apk.knopf":"Download the latest version","lv.an.apk.m1":"Open the Mining tab and scroll to “Controls”.","lv.an.apk.m2":"Choose the mode: Solo or Pool. In pool mode the app suggests an open pool; tap “Change” to see all pools with their miners, hash power, blocks found and fee. A full pool cannot be selected.","lv.an.apk.m3":"Set “Workers” and “Duty cycle”. Workers are the processor cores that compute; the duty cycle sets how hard they work (25 to 100 %).","lv.an.apk.m4":"Tap “Start mining”. If Android asks about notifications, allow them: that is how you see that mining is running, and you can stop it from there.","lv.an.apk.name":"On your phone this app is called “YSKAR Wallet”. It is a different app from the new YSKAR Wallet without mining, and both can be installed side by side; your 12 words work in both.","lv.an.apk.pruefen":"Checking the download (optional)","lv.an.apk.pruefenText":"Every release also contains a file ending in <code>.sha256</code>. It holds the checksum of the APK. If the checksum of your download matches, the file is exactly the one we published.","lv.an.apk.s1":"On your phone, open the download page and tap the file <code>yskar-wallet-….apk</code>.","lv.an.apk.s2":"Android asks whether apps from this source (for example your browser) may be installed. Tap “Settings” and allow it for this source.","lv.an.apk.s3":"Go back and tap “Install”. Google Play Protect may show a warning; this is normal for apps from outside the Play Store.","lv.an.apk.s4":"Open the app, create a wallet or restore your existing one with your 12 words.","lv.an.apk.start":"Starting mining","lv.an.apk.text":"The Android app keeps mining in the background, even with the screen locked, and shows your mining in a widget on the home screen. Because Google Play does not allow on-device mining, this version is available directly from us.","lv.an.apk.tipp":"Our recommendation: all workers, duty cycle 25 %, in the pool. That is easy on battery and temperature, and in the pool smaller amounts arrive more regularly. “Calibrate device” finds the best number of workers for your phone.","lv.an.apk.titel":"Android app with mining","lv.an.apk.update":"Updating the app","lv.an.apk.updateText":"When a new version is available, the app shows a notice when you open it. Tap “Download”: the app fetches the update, then Android asks whether to install it. Your wallet is kept. To check by hand, go to Settings → App → Updates in the app.","lv.an.apk.w1":"Press and hold an empty spot on the home screen, choose “Widgets” and drag “YSKAR Wallet” onto the screen.","lv.an.apk.w2":"While mining runs, the widget shows what you have earned in this session, plus hashrate, runtime and accepted shares. “Stop” ends mining straight from the home screen. When mining is stopped, you see the current block, the network hashrate and the block reward.","lv.an.apk.w3":"“Earned this session” counts the block rewards and pool payouts credited to your address since you started; the value changes when a new block is found. Choose light or dark in the app under Settings → App → Widget. The widget in this form is available from version 1.1.0.","lv.an.apk.widget":"Widget on the home screen","lv.an.etikett":"Guides","lv.an.ex.p1":"Search by block height, hash or address.","lv.an.ex.p2":"For every block you see who found it: a name, a pool or a solo address.","lv.an.ex.p3":"Enter your own address to check your payouts.","lv.an.ex.text":"The <a href=\"/explorer\">explorer</a> shows every block, every transfer and every address. It reassembles each block header in your browser, hashes it and checks the proof of work and the chain. Transfers, signatures and balances are checked by full nodes – run one, and you do not have to believe anyone.","lv.an.ex.titel":"The explorer","lv.an.gr.aus":"How a pool pays out","lv.an.gr.aus1":"The block itself pays everyone directly. The pool operator never holds your money, and there is no payout threshold.","lv.an.gr.aus2":"What counts is the work of the recent past, measured in shares. If you have only just started, your part of the first block is correspondingly small.","lv.an.gr.gebuehr":"The operator may take a fee between 0 and 5 %. It is shown in the pool list.","lv.an.gr.hinweis":"Nobody can promise you a return. How often you receive something depends on your computing power, on the power of the network and on chance.","lv.an.gr.p1":"YSKAR is a blockchain of its own. A new block is found about every 10 minutes. Whoever finds it receives the reward – currently 875 YSR – directly on their address.","lv.an.gr.p2":"To find a block, your device tries out numbers (double SHA-256). The more computing power you have, the better your chances. The difficulty adjusts to the power of the whole network.","lv.an.gr.plaetze":"A block can pay out at most 64 addresses, so a pool has at most 64 places (63 when it takes a fee). A place counts only while you mine: a new device holds it on trial for 2 minutes and keeps it by delivering shares regularly. Places of miners who stop become free again.","lv.an.gr.pool":"<strong>Pool:</strong> many search together. When the pool finds a block, the reward is split by the work contributed. Smaller amounts, but more regularly.","lv.an.gr.solo":"<strong>Solo:</strong> you search on your own. If you find a block, the whole reward is yours. That can take a long time.","lv.an.gr.sp":"Solo or pool","lv.an.gr.titel":"How mining works","lv.an.hi.a1":"Android is closing the app to save battery. Set the battery usage of YSKAR Wallet to “Unrestricted” (Settings → Apps → YSKAR Wallet → Battery).","lv.an.hi.a2":"A pool has at most 64 places. A place is freed at once when a miner stops, and up to 20 minutes after a miner goes silent, so trying again later can work. Otherwise choose another pool or mine solo. If your address already has a place, further devices can still join.","lv.an.hi.a3":"The node has not found another node yet. Check your internet connection and whether you allowed Node Core in the Windows firewall prompt. Then wait a moment.","lv.an.hi.a4":"The node is still synchronising. Mining starts once the overview shows “In sync”.","lv.an.hi.a5":"Graphics card mining needs an NVIDIA, AMD or Intel card with a current driver. Install the current driver from the card maker and restart Node Core. Before a card mines, it runs a self-test; a card that fails is not used.","lv.an.hi.a6":"Restore the wallet with the same 12 words, in the same order. A different set of words is a different wallet.","lv.an.hi.a7":"Ask questions in the <a href=\"https://t.me/+GxAmtTMeG1w1M2Yy\">community chat on Telegram</a>. Report bugs on <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a>. Never share your 12 words: admins never message you first.","lv.an.hi.f1":"Mining on the phone stops by itself","lv.an.hi.f2":"“Pool full”","lv.an.hi.f3":"Node Core: “No peer connected yet”","lv.an.hi.f4":"Node Core: mining does not start","lv.an.hi.f5":"The graphics card is not found","lv.an.hi.f6":"My balance is missing on a new device","lv.an.hi.f7":"Something else","lv.an.hi.titel":"If something does not work","lv.an.mini.hinweis":"Tip: in the Mining tab you can choose between solo and pool. In the pool you receive smaller amounts more often; solo means rarer but whole blocks.","lv.an.mini.s1":"Open <a href=\"https://t.me/YSKAR_bot\">@YSKAR_bot</a> in Telegram and start the app.","lv.an.mini.s2":"Tap “Create wallet”. The app shows you 12 words: write them down on paper, in order.","lv.an.mini.s3":"Confirm a few of the words and choose a PIN.","lv.an.mini.s4":"Open the Mining tab and tap “Start mining”. Keep the app open while it computes.","lv.an.mini.text":"The fastest way in. The Mini App runs inside Telegram; there is nothing to install.","lv.an.mini.titel":"Telegram Mini App","lv.an.nc.e1":"<strong>Node:</strong> data folder, ports and seed are filled in. The defaults suit most people – just click “Continue”.","lv.an.nc.e2":"<strong>Wallet:</strong> create a new wallet and write down the 12 words, or bring your existing wallet over with your 12 words. Choose a password of at least 8 characters; it encrypts the words on this PC. You can also set up the wallet later.","lv.an.nc.e3":"<strong>Start:</strong> click “Start node”.","lv.an.nc.einst":"Settings","lv.an.nc.erst":"First start","lv.an.nc.firewall":"On the first start Windows asks whether Node Core may access the network. Allow it, otherwise the node cannot find other nodes.","lv.an.nc.firewallLinux":"On Linux there is no such prompt. If a firewall is active (such as ufw), allow port 8646 – otherwise other nodes cannot reach yours. Your own connections work either way.","lv.an.nc.i1":"Download the installer and run it.","lv.an.nc.i2":"Windows shows “Windows protected your PC” because the installer is not signed. Choose “More info”, then “Run anyway”.","lv.an.nc.i3":"Follow the installer. Node Core starts afterwards.","lv.an.nc.inst":"Installing on Windows","lv.an.nc.l1":"<strong>Ubuntu, Debian, Linux Mint:</strong> download the <code>.deb</code> file and install it in a terminal. Then start “YSKAR Node Core” from the application menu.","lv.an.nc.l2":"<strong>Other distributions:</strong> download the AppImage, make it executable and start it. AppImages need FUSE 2 (on Ubuntu the package <code>libfuse2</code>).","lv.an.nc.l3":"Node Core for Linux runs on 64-bit PCs (x86-64) with a desktop. ARM computers such as the Raspberry Pi are not supported.","lv.an.nc.linux":"Installing on Linux","lv.an.nc.m1":"Choose the target: Solo or Pool. In pool mode pick a pool from the list, or enter an address under “Your own pool address” and check it.","lv.an.nc.m2":"“Reward goes to”: your own wallet or another address.","lv.an.nc.m3":"Choose the device: processor, graphics card or both. Set the number of cores and the load per core.","lv.an.nc.m4":"Solo only: if you like, enter a name that appears in the blocks you find. It is public and permanent.","lv.an.nc.m5":"Click “Start mining”.","lv.an.nc.mining":"Mining","lv.an.nc.poolHinweis":"If a pool no longer accepts you, mining stops and tells you why. It never silently continues solo.","lv.an.nc.port":"Do I have to open a port?","lv.an.nc.portText":"No. Without it your node connects to other nodes by itself. If you forward port 8646 in your router, other nodes can reach yours as well. That helps the network but is optional.","lv.an.nc.pruefen":"To be sure the file is the one we published, compare its checksum with the <code>.sha256</code> file of the release. In PowerShell:","lv.an.nc.pruefenLinux":"On Linux:","lv.an.nc.s1":"<strong>Start with Windows</strong> (on Linux: “Start when you log in”): Node Core starts without a window when you sign in.","lv.an.nc.s2":"<strong>Keep running when closed:</strong> the window disappears into the notification area next to the clock, the node keeps working.","lv.an.nc.s3":"<strong>Resume mining after start:</strong> mining continues with the last settings as soon as the node is in sync.","lv.an.nc.s4":"<strong>Updates:</strong> Node Core tells you when a new version is available. Nothing is installed by itself.","lv.an.nc.sig":"Signing and YSKAR Lab","lv.an.nc.sigText":"Since version 1.1.0, “Sign” in the wallet signs a text with your address, for example to prove that an address is yours; “Verify” checks a signed message from someone else. On <a href=\"https://lab.yskar.app\">lab.yskar.app</a>, “Sign in with wallet” opens Node Core: it shows the website, your address and how long the request is valid, and signs only after you confirm with your password. A signature cannot move YSR.","lv.an.nc.sync":"The first synchronisation","lv.an.nc.syncText":"On the first start Node Core downloads the whole blockchain and checks every block. That can take a while; the overview shows the progress. Mining only starts once the node has caught up with the network.","lv.an.nc.text":"Node Core is the YSKAR program for Windows and Linux: your own node with wallet and mining in one window. It downloads the blockchain to your PC and checks every block itself.","lv.an.nc.titel":"Node Core for Windows and Linux","lv.an.nc.update":"Updating","lv.an.nc.updateText":"Download the new installer, quit Node Core – also in the notification area – and run the installer. Your wallet and the blockchain are kept.","lv.an.nc.v1":"Windows 10 or 11 (64-bit) or Linux (64-bit, x86-64) and an internet connection","lv.an.nc.v2":"Disk space for the blockchain. It is still small and grows with every block.","lv.an.nc.v3":"For mining with a graphics card: an NVIDIA, AMD or Intel card with a current driver. Without one, the processor does the work.","lv.an.nc.vor":"What you need","lv.an.nc.w1":"<strong>Send:</strong> enter recipient and amount, review, confirm with your password. The password is asked before every transfer.","lv.an.nc.w2":"<strong>Receive:</strong> show your address or its QR code.","lv.an.nc.w3":"<strong>Contacts:</strong> names instead of addresses, stored only on this PC.","lv.an.nc.w4":"<strong>Lock:</strong> the wallet locks itself after 10 minutes without activity and whenever Windows is locked. You can change the time in the settings.","lv.an.nc.wallet":"Wallet","lv.an.node.s1":"1. Build","lv.an.node.s2":"2. Start and connect to the network","lv.an.node.s2Text":"The node connects to another node (the seed), loads the chain and checks it block by block. Other nodes can reach yours on port 8646 if you open it in your router; this is optional. With --no-upstream your node passes blocks on only to other nodes, not to the project’s web server.","lv.an.node.s3":"3. Mine against your own node","lv.an.node.s4":"4. Run a pool (optional)","lv.an.node.s4Fuss":"--pool-fee is in basis points: 100 = 1.00 %, at most 500.","lv.an.node.s4Mehr":"What a pool needs so that the app and other miners can reach it is described under <a href=\"/anleitungen#pool\">Running a pool</a>.","lv.an.node.s4Text":"Any node can be a pool, without registration. The block itself pays all participants; you never hold anyone else’s funds.","lv.an.node.s5":"5. As a service on a Raspberry Pi","lv.an.node.s5Text":"So the node starts on its own after a restart, set it up as a systemd service. The ready-made files and a guide are in the repository under <a href=\"https://github.com/dabitlex/YSKAR/tree/main/deploy\"><code>deploy/</code></a>.","lv.an.node.text":"A full node downloads the chain and checks every block itself – proof of work, signatures, balances. It needs Node.js 22.13 or newer and runs well on a Raspberry Pi.","lv.an.node.titel":"Running a full node","lv.an.node.win":"On Windows, use npm.cmd instead of npm.","lv.an.pc.s1":"1. Install Node.js","lv.an.pc.s1Text":"The miner needs Node.js 20 or newer. Download the LTS version from <a href=\"https://nodejs.org\">nodejs.org</a> and install it. On Windows, open a new command window afterwards.","lv.an.pc.s2":"2. Get the miner","lv.an.pc.s2Text":"There is nothing else to install. The self-test checks that your computer computes hashes correctly.","lv.an.pc.s3":"3. Start mining","lv.an.pc.s3Text":"Replace the address with your own YSKAR address (it starts with ysr1). With the pool:","lv.an.pc.s4":"4. Graphics card (optional)","lv.an.pc.s4Text":"With a graphics card, add <code>--gpu</code>. This needs a GPU program: <code>yskar-cuda</code> for NVIDIA cards, <code>yskar-opencl</code> for AMD and Intel cards. The miner takes the first one that finds a card; <code>--gpu-api opencl</code> uses the AMD and Intel program even if an NVIDIA card is present. For Linux both are attached to every Node Core release (<code>yskar-cuda-…-linux-x86_64</code>, <code>yskar-opencl-…-linux-x86_64</code>); on Windows, build them as described in the repository under <code>node-core/gpu</code>.","lv.an.pc.s5":"5. Mining rigs with HiveOS","lv.an.pc.s5Text":"For mining rigs with HiveOS there is a ready package: this miner with the GPU program, one miner per graphics card from NVIDIA, AMD or Intel, no fee. It is attached to every Node Core release as <code>yskar-hiveos-….tar.gz</code>. How to set up the flight sheet is described in <a href=\"https://github.com/dabitlex/YSKAR/blob/main/hiveos/README.md\">hiveos/README.md</a>.","lv.an.pc.solo":"Solo instead of pool: leave out --mode pool. Whole blocks, but more rarely.","lv.an.pc.text":"The miner runs on Windows, macOS and Linux. It only needs an address – no private key, no wallet, no sign-up. You can safely run it on any computer.","lv.an.pc.titel":"PC miner","lv.an.pool.beitritt":"How miners join","lv.an.pool.beitrittText":"In the app choose “Pool” and enter the address of your pool under “Custom address”; in Node Core under “Your own pool address”. With the PC miner:","lv.an.pool.caddy":"The configuration for Caddy. Replace the name with yours; it must point to your machine first.","lv.an.pool.g1":"<strong>Name:</strong> 3 to 32 simple characters. It is written into every block of your pool and stays there for good.","lv.an.pool.g2":"<strong>Fee:</strong> 0 to 5 %. In the command <code>--pool-fee</code> is given in basis points: 100 = 1 %. With a fee you must name the address it goes to.","lv.an.pool.g3":"<strong>Places:</strong> at most 64 addresses, with a fee 63 – one recipient is you.","lv.an.pool.g4":"<strong>No foreign money:</strong> the block pays everyone directly. You never hold funds of your miners.","lv.an.pool.h1":"Open “Run a pool”, set name, fee and number of places, and switch it on.","lv.an.pool.h2":"Under Mining choose “Pool”. Your own pool is listed first.","lv.an.pool.h3":"For more PCs switch on “Devices in your home network”. They connect with <code>http://&lt;address of this PC&gt;:8645</code>.","lv.an.pool.heim":"In your home network with Node Core","lv.an.pool.heimText":"The pool in Node Core answers only your own PC and your own network. It cannot be reached from the internet this way.","lv.an.pool.k1":"Who mines with you","lv.an.pool.k2":"What you need","lv.an.pool.liste":"Getting into the pool list","lv.an.pool.listeText":"The app and Node Core show a maintained list of pools. For an entry your pool must be reachable over HTTPS and answer <code>/api/v2/pool</code>. Ask for it on <a href=\"https://github.com/dabitlex/YSKAR/issues\">GitHub</a>. The list is neither a check nor a recommendation: a pool reports its miners, power and fee itself.","lv.an.pool.n1":"<strong>A node that runs all the time.</strong> Best is the command-line node on a Raspberry Pi or a server – see <a href=\"/anleitungen#fullnode\">Running a full node</a>.","lv.an.pool.n2":"<strong>A name</strong> under which it can be reached: a domain of your own or a free DynDNS name.","lv.an.pool.n3":"<strong>HTTPS with a valid certificate.</strong> Telegram and browsers do not load anything unencrypted. Without HTTPS no phone reaches your pool.","lv.an.pool.n4":"<strong>A web server in front</strong> that fetches the certificate and passes requests on to the node, for example Caddy.","lv.an.pool.n5":"<strong>Port 443 open.</strong> For a node at home that means a port forwarding in your router.","lv.an.pool.netz":"For the app, the Mini App and miners from the internet","lv.an.pool.netzText":"This is what you need:","lv.an.pool.o1":"<strong>At home:</strong> no extra cost. But your IP address becomes publicly known, you need a port forwarding, and your connection carries the load.","lv.an.pool.o2":"<strong>Rented server:</strong> your home IP address stays out of it, and no keys are stored on the server – only the address for the fee. Read the provider’s terms first: many forbid mining or anything related to it. Get the permission in writing.","lv.an.pool.ort":"At home or on a rented server?","lv.an.pool.r1a":"You and devices in your home network","lv.an.pool.r1b":"Node Core with “Run a pool” switched on","lv.an.pool.r2a":"PC miners from the internet","lv.an.pool.r2b":"A node that runs all the time and can be reached from outside","lv.an.pool.r3a":"The app and the Mini App","lv.an.pool.r3b":"In addition HTTPS: a name (domain or DynDNS) and a certificate","lv.an.pool.regeln":"Rules for every pool","lv.an.pool.start":"Start the node as a pool. It listens only on the machine itself; the web server stands in front of it.","lv.an.pool.test":"Check from outside. If the answer contains your pool name and the number of places, the pool is reachable.","lv.an.pool.text":"A YSKAR pool is not a service with accounts. It is a node that splits the reward of its blocks. Anyone can run one, without registration. What you need depends on who is supposed to mine with you.","lv.an.pool.titel":"Running a pool","lv.an.si.p1":"<strong>Your 12 words are your wallet.</strong> Never type them into a website, never send them to anyone. Nobody from YSKAR will ask for them.","lv.an.si.p2":"<strong>Download only from yskar.app and the YSKAR project on GitHub.</strong> If you want to be sure, compare the checksum.","lv.an.si.p3":"<strong>Keep your software up to date.</strong> At an announced rule change, an outdated node either stops at that block or keeps running without checking the new rule – both are reasons to update in time.","lv.an.si.p4":"<strong>Running a node:</strong> other nodes see your IP address, as in every peer-to-peer network. You do not need a port forwarding. If you do not want your address to be visible, use a VPN.","lv.an.si.p5":"<strong>Node Core:</strong> wallet and interface can only be reached from your own PC.","lv.an.si.titel":"Security","lv.an.text":"Everything explained step by step: mining on the phone and on the PC, your wallet, your own node and your own pool.","lv.an.titel":"Step by step","lv.an.tocLabel":"On this page","lv.an.ue.k1":"Way","lv.an.ue.k2":"Good for","lv.an.ue.k3":"You need","lv.an.ue.r1a":"Telegram Mini App","lv.an.ue.r1b":"Trying it out, right away","lv.an.ue.r1c":"Telegram","lv.an.ue.r2a":"Android app","lv.an.ue.r2b":"Mining in the background on your phone","lv.an.ue.r2c":"An Android phone","lv.an.ue.r3a":"Node Core","lv.an.ue.r3b":"Your own node with wallet and mining on a PC, graphics card included","lv.an.ue.r3c":"Windows 10/11 or Linux (64-bit)","lv.an.ue.r4a":"PC miner","lv.an.ue.r4b":"Mining from the command line","lv.an.ue.r4c":"Windows, macOS or Linux with Node.js","lv.an.ue.r5a":"Full node","lv.an.ue.r5b":"A node or a pool on a Raspberry Pi or a server","lv.an.ue.r5c":"Linux, Windows or macOS with Node.js 22.13 or newer","lv.an.ue.text":"There are five ways to take part. All of them use the same wallet: with your 12 words you reach the same balance everywhere.","lv.an.ue.titel":"Which way suits you?","lv.an.w.empfangen":"Receiving","lv.an.w.empfangenText":"Show your address or its QR code. You can add an amount and a note to the code; the sender then only has to confirm. You may share your address with anyone – your 12 words with nobody.","lv.an.w.kontakte":"Contacts and history","lv.an.w.kontakteText":"Contacts give addresses a name; they are stored only on your device. The history shows every payment; mining income of one day is bundled into one line and can be opened down to the single block.","lv.an.w.s1":"Recipient: paste the address, scan the QR code or choose a contact. A YSKAR address starts with ysr1.","lv.an.w.s2":"Amount, and a note of up to 32 bytes if you like – that is 32 plain Latin letters, fewer with accents or other scripts. The note is stored publicly in the blockchain.","lv.an.w.s3":"Fee: the app suggests it. When the network is not busy, the minimum fee is enough for the next block.","lv.an.w.s4":"Review: the app shows the full address and tells you whether you have sent there before. Confirm with your PIN or fingerprint.","lv.an.w.senden":"Sending","lv.an.w.warn":"A payment that has been sent cannot be taken back. Check the whole address before you confirm.","lv.an.wallet.p1":"Write the words down on paper, in the right order. No screenshot, no cloud.","lv.an.wallet.p2":"Keep the paper safe. If you lose your phone, the words restore everything.","lv.an.wallet.p3":"The PIN only protects the app on this device. It cannot replace the words.","lv.an.wallet.p4":"To move to a new device, choose “I already have twelve words” and enter them.","lv.an.wallet.text":"Your wallet is created on your device from 12 words. These words are your key: whoever has them can access the funds – on any device, in any YSKAR app.","lv.an.wallet.titel":"Your wallet","lv.fuss.datenschutz":"Privacy","lv.fuss.impressum":"Legal notice","lv.hood.f2.k":"Difficulty","lv.nc.appimage":"AppImage for other Linux distributions","lv.nc.bildNotiz":"Example view – the numbers are examples.","lv.nc.knopfLinux":"Download for Linux (.deb)","lv.nc.knopfWin":"Download for Windows","lv.nc.mehr":"Checksum and release notes","lv.nc.system":"Windows 10 or 11 (64-bit)","lv.nc.systemLinux":"Linux 64-bit · Ubuntu, Debian, Mint","lv.pr.block.alt":"The 136-byte block header and its ten fields","lv.pr.block.merkle":"One hash over all transactions in the block. A single changed byte in any transfer changes it.","lv.pr.block.nonce":"The number miners vary. The first 128 bytes stay the same for a job, so each try needs only two SHA-256 compression steps.","lv.pr.block.prev":"The hash of the previous block. It links the chain: changing an old block would change every hash after it.","lv.pr.block.state":"One hash over all accounts (balance and nonce) after this block. Every node computes it itself and compares.","lv.pr.block.text":"Every block starts with exactly 136 bytes. Its hash is double SHA-256 over these bytes, and it must not exceed the target that the difficulty sets.","lv.pr.block.titel":"Anatomy of a block header","lv.pr.db.ablauf":"Expiry","lv.pr.db.ablaufWert":"optional, by block height","lv.pr.db.adresse":"Address","lv.pr.db.adresseWert":"ysr1…, 42 characters; shared accounts from V6: ysr1p…, 63 characters (bech32m)","lv.pr.db.blockzeitWert":"600 seconds (target)","lv.pr.db.diffWert":"LWMA over 45 blocks, every block","lv.pr.db.einheit":"Smallest unit","lv.pr.db.gebuehr":"Fees go to","lv.pr.db.gebuehrWert":"the miner of the block","lv.pr.db.kette":"The chain","lv.pr.db.knoten":"Full nodes","lv.pr.db.knotenWert":"each keeps and checks the whole chain","lv.pr.db.konsens":"Consensus","lv.pr.db.konsensWert":"Proof of work, SHA-256d","lv.pr.db.memo":"Memo","lv.pr.db.memoWert":"up to 32 bytes","lv.pr.db.minGeb":"Minimum fee (consensus)","lv.pr.db.minGebWert":"1 unit per byte","lv.pr.db.modell":"Model","lv.pr.db.modellWert":"accounts with balance and nonce","lv.pr.db.muenze":"The coin","lv.pr.db.name":"Name · ticker","lv.pr.db.netz":"Network","lv.pr.db.notfall":"Emergency rule","lv.pr.db.notfallWert":"easier after 30 min without a block","lv.pr.db.nullkonto":"Burn address","lv.pr.db.pfad":"Key derivation","lv.pr.db.pool":"Pools","lv.pr.db.poolWert":"paid from the block, fee 0–5 %","lv.pr.db.relay":"Minimum fee to relay","lv.pr.db.relayWert":"10 units per byte","lv.pr.db.sig":"Signatures","lv.pr.db.staub":"Smallest amount to send","lv.pr.db.staubWert":"100 units","lv.pr.db.transfer":"Transfer size","lv.pr.db.transferWert":"168 to 200 bytes","lv.pr.db.tx":"Transactions per block","lv.pr.db.txWert":"up to 2,000","lv.pr.db.vorab":"Pre-mine · allocation","lv.pr.db.vorabWert":"none","lv.pr.db.wahl":"Chain selection","lv.pr.db.wahlWert":"most accumulated work","lv.pr.db.wallet":"Wallets and accounts","lv.pr.db.worte":"Seed words","lv.pr.db.worteWert":"BIP39, 12 or 24 words","lv.pr.etikett":"The protocol in detail","lv.pr.gen.belohnung":"Reward","lv.pr.gen.belohnungWert":"875 YSR, unspendable","lv.pr.gen.text":"The first block of the chain. Its coinbase carries a short message, and its reward went to an address nobody can spend from.","lv.pr.gen.titel":"Block 0","lv.pr.gen.zeit":"Timestamp","lv.pr.pruefen":"Check block 0 or the latest block yourself, right in your browser.","lv.pr.text":"Everything below is fixed in the consensus code and the same for every node. Nothing depends on a server, a company or a setting.","lv.pr.titel1":"YSKAR and YSR,","lv.pr.titel2":"byte by byte.","lv.pr.tx.alt":"Fields of a transfer","lv.pr.tx.p1":"The signature also covers the chain ID, so a transfer signed for YSKAR is invalid on any other network.","lv.pr.tx.p2":"The nonce counts the transfers an account has sent. The same transfer can never be applied twice.","lv.pr.tx.p3":"An optional expiry height lets a transfer lapse if it has not been included by then.","lv.pr.tx.text":"A transfer moves YSR from one account to another. It is 168 bytes plus an optional memo.","lv.pr.tx.titel":"Anatomy of a transfer","lv.recht.nurDeutsch":"This page is in German, as required by German law.","lv.supply.aera.fuss":"Rewards are counted in whole base units (0.00000001 YSR), so each halving drops the remainder: in total 20,999,999.99832 YSR will ever be issued, slightly below the maximum.","lv.supply.aera.k1":"Era","lv.supply.aera.k2":"Blocks","lv.supply.aera.k3":"Reward per block","lv.supply.aera.k4":"Issued in the era","lv.supply.aera.k5":"Total after the era","lv.supply.aera.text":"An era lasts 12,000 blocks, about 83 days. In each era the reward is half of the one before. From block 444,000 no new YSR are created and miners receive the fees only.","lv.supply.aera.titel":"Issuance by era","lv.wallet.warnung":"<strong>Whoever has the 12 words has the funds.</strong> Never share them. Nobody from YSKAR will ever ask you for them.","lv.wpseite.drucken":"Print / save as PDF","lv.wpseite.toc":"Contents","lv.wpseite.untertitel":"A proof-of-work blockchain that anyone can mine and anyone can verify.","lv.zahlen.blockzeit":"Block time","unit.min":"{n} min","unit.hours":"{n} hours","unit.days":"{n} days","ago.sec":"{n} s ago","ago.min":"{n} min ago","ago.hours":"{n} h ago","ago.days":"{n} days ago","eta.around":"in about {d}, around {date}","v6.active":"Active since block 10,000","v6.pending":"{n} blocks to go","mode.live":"Live from the chain","mode.snapshot":"State of {date}","mode.history":"History up to block {h}","mode.liveShort":"Live","mode.snapshotShort":"Last known state","dur.years":"{n} years","dur.days":"{n} days","dur.hours":"{n} hours","dur.min":"{n} minutes","dur.sec":"{n} seconds","rm.run.p":"Released and in use. Each entry leads to the place where you can check it.","rm.run.1.h":"Main network","rm.run.1.p":"Blocks since 9 Sep 2026. The chain is at block","rm.run.1.l":"The network, live","rm.run.2.h":"Consensus revisions 2 to 5","rm.run.2.p":"Active since blocks 2,000, 4,000, 6,000 and 7,000.","rm.run.2.l":"What each one changed","rm.run.3.p":"Full node, wallet, CPU and GPU mining and pool operation for Windows and Linux.","rm.run.3.l":"Download","rm.run.4.p":"The Android wallet: send, receive, sign. Ready for revision 6.","rm.run.4.l":"About the wallet","rm.run.5.h":"Three public pools","rm.run.5.p":"YSKAR MAIN, Gozero and ODW.Serv. The pool software is open; anyone can run one.","rm.run.5.l":"The pools, live","rm.run.6.h":"Explorer and public API","rm.run.6.p":"Every block, transfer and address, in the browser and over HTTP.","rm.run.6.l":"Open the explorer","rm.run.7.p":"Proposals, discussion and status in the open. You sign in with your wallet.","rm.fix.p":"These changes are written into the consensus code. They take effect at a block and not on a date: when that block comes depends on how fast blocks are found.","rm.fix.blocks":"blocks","rm.fix.1.at":"Block 10,000","rm.fix.1.h":"Revision 6","rm.fix.1.p":"Shared accounts with up to 16 keys, time locks and hash locks, batch transfers to up to 1,000 recipients and room for 5,000 transactions per block. A hard fork, set after a community vote on 25 Oct 2026. Nodes must run a current release before that block.","rm.fix.1.l":"What changes at block 10,000","rm.fix.2.at":"Block 12,000","rm.fix.2.h":"First halving","rm.fix.2.p":"The block reward falls from 875 to 437.5 YSR. It halves again every 12,000 blocks.","rm.fix.2.l":"The whole schedule","rm.fix.after":"The last new YSR is created in block 443,999. After that, miners earn fees only.","rm.plan.p":"Intended, not promised. Nothing here has a date, and the order can change.","rm.plan.1.h":"Swaps and instant payments","rm.plan.1.p":"Revision 6 brings the building blocks to the chain: hash locks and time locks. Wallet functions that use them for swaps and for payments in real time come after it.","rm.plan.2.h":"Stratum for mining rigs","rm.plan.2.p":"Today miners and pools speak YSKAR's own HTTP protocol. Stratum is planned for when the network has grown.","rm.plan.3.h":"Mining to shared accounts","rm.plan.3.p":"Revision 6 cannot pay a block reward to a shared account. The specification leaves that to revision 7.","rm.plan.4.h":"The wallet with your own node","rm.plan.4.p":"Today YSKAR Wallet reads balances from the public server. Planned: point it at a full node you run yourself.","rm.plan.5.h":"YSKAR Wallet in the Play Store","rm.plan.5.p":"Today the wallet is an APK from GitHub Releases.","rm.plan.6.h":"Public test network and community decisions","rm.plan.6.p":"The next stages of YSKAR Lab: try changes before they reach the main network, and decide on them together.","rm.plan.7.h":"Exchange listings","rm.plan.7.p":"In preparation, with no date and no names. Today YSR has no price and no market, and nobody should mine in the expectation that this will change.","rm.how.p":"Proposals are written, discussed and tracked in public at YSKAR Lab. A change to the consensus rules needs a specification, and it reaches the main network only at a block height that every node knows in advance.","com.ch.p":"Announcements appear in the Telegram channel first. Everything else is for questions and discussion.","com.ch.1":"Releases and news.","com.ch.2":"Questions and discussion with other miners and users.","com.ch.3":"Short updates from @yskar_official.","com.ch.4":"The announcement thread.","com.ch.5":"Source code, releases and issues.","com.ch.6":"Proposals, from the first idea to the release.","com.do.1.h":"Run a full node","com.do.1.p":"Every node that checks the blocks itself makes the network depend less on any single server.","com.do.2.h":"Mine, alone or in a pool","com.do.2.p":"Hash power that is spread over many miners and several pools makes the chain harder to steer.","com.do.3.h":"Run a pool","com.do.3.p":"The pool software is part of the repository and pays miners in the block itself. Another independent pool spreads the hash power further.","com.do.4.h":"Test and report","com.do.4.p":"Try a release and open an issue for what breaks. Say what you saw and how to reproduce it.","com.do.5.h":"Propose and discuss","com.do.5.p":"Bring an idea to YSKAR Lab, or improve someone else's in the comments.","com.lab.p":"Every proposal moves through the same six stages, and everyone can see where it stands.","com.lab.s1":"Idea","com.lab.s1.d":"Share what you have in mind.","com.lab.s2":"Discussion","com.lab.s2.d":"Improve it together in the comments.","com.lab.s3":"Draft","com.lab.s3.d":"Text, design, specification or code.","com.lab.s4":"Planned","com.lab.s4.d":"Set for a coming release, with a reason.","com.lab.s5":"On testnet","com.lab.s5.d":"Try it before it reaches the main network.","com.lab.s6":"Shipped","com.lab.s6.d":"Released, with a link to it.","com.lab.k1":"The author moves a proposal through the first three stages.","com.lab.k2":"From Planned on, the team sets the stage, always with a reason.","com.lab.open":"Open YSKAR Lab","com.safe.1.h":"Your 12 words stay with you","com.safe.1.p":"Nobody from YSKAR will ever ask for your 12 words, your PIN or a wallet file. Whoever asks is trying to take your coins.","com.safe.2.h":"Download from the source","com.safe.2.p":"Get the software from the GitHub releases that this site links to, and compare the wallet's certificate fingerprint before you install it.","com.safe.3.h":"No promises","com.safe.3.p":"YSR has no price and no market today, and it is not listed on any exchange. Nothing here promises that this will change.","com.channel":"Telegram channel","com.chat":"Community chat","wallet.dl":"Download the APK","wallet.meta":"Version 2.0.0, for Android 7 or newer. Open source under the MIT License. English and German.","wallet.feat.p":"No ads, no tracking and no account with anyone. The app talks to the YSKAR network and to nothing else.","wallet.f1.h":"Your key stays with you","wallet.f1.p":"The wallet is created on your phone. 12 recovery words restore it on any device. They are stored encrypted with your PIN in Android's protected storage and never go into cloud backups.","wallet.f2.h":"Send on purpose","wallet.f2.p":"Enter an address, pick a contact or scan a QR code. Before sending you see recipient, amount and network fee once more, then you slide to confirm. A transfer cannot be taken back.","wallet.f3.h":"Receive and request","wallet.f3.p":"Show your QR code or your address. If you like, ask for a specific amount: the sender then only has to confirm.","wallet.f5.h":"Sign and sign in","wallet.f5.p":"Prove with a signed message that an address is yours, and check other people's signatures. Sign in to YSKAR Lab with a QR code. A signature cannot move YSR.","wallet.f6.h":"Locked down","wallet.f6.p":"PIN and fingerprint, automatic lock after a time you choose, no screenshots while the 12 words are on screen, and the app's own keyboard, so no input passes through your phone's keyboard app.","wallet.inst.h":"Install in four steps","wallet.inst.p":"The wallet is distributed as an APK through its GitHub releases. Updates install over the previous version and your wallet stays on the device.","wallet.inst.1":"Open the <a class='ext' href='https://github.com/dabitlex/YSKAR--WALLET/releases/latest' target='_blank' rel='noopener'>latest release</a> on your Android phone and download the file <code>yskar-wallet-…apk</code>.","wallet.inst.2":"Open the file. Allow installing from this source when Android asks.","wallet.inst.3":"Tap “Create wallet” and write the 12 words down on paper, in order.","wallet.inst.4":"Choose a PIN. To move an existing wallet over, enter its 12 words instead.","wallet.verify.h":"Check that the file is genuine","wallet.verify.p":"Every release is signed with the same key. This is the SHA-256 fingerprint of its certificate. If the fingerprint of your download differs, do not install the file.","wallet.oth.h":"Other places for your YSR","wallet.oth.p":"Every YSKAR app uses the same 12 words. With them you reach the same balance everywhere.","wallet.oth.1.h":"YSKAR Wallet","wallet.oth.1.p":"Android. Send, receive, sign. It does not mine.","wallet.oth.2.h":"Node Core","wallet.oth.2.p":"Windows and Linux. A wallet inside your own full node, with mining and message signing. <a href='/mining#setup'>Get Node Core</a>","wallet.oth.3.h":"Android app with mining","wallet.oth.3.p":"Wallet and mining on the phone, with a home-screen widget and notifications.","wallet.oth.4.h":"Telegram Mini App","wallet.oth.4.p":"The easy way in, with nothing to install. Ownership depends on your 12 words, not on your Telegram account.","wallet.st.h":"Where the wallet stands","wallet.st.1.h":"Android only","wallet.st.1.p":"The wallet is an APK from GitHub. It is not in an app store, and there is no iOS app.","wallet.st.2.h":"Ready for revision 6","wallet.st.2.p":"Version 2.0.0 knows the new transfer format and switches to it at block 10,000. An older version still receives YSR but cannot send after that block.","wallet.st.3.h":"Planned: an app store","wallet.st.3.p":"A release through Google Play is planned. There is no date.","wallet.st.4.h":"Planned: your own node","wallet.st.4.p":"Today the wallet reads from the project's main node. Connecting it to a node you run yourself is planned, so that nobody has to take the project's word for a balance.","mining.ways.p":"Every way is free and uses the same wallet: with your 12 words you reach the same YSR everywhere.","mining.tab.pc":"PC","mining.tab.phone":"Phone","mining.tab.cli":"Command line","mining.tab.rig":"Rig","mining.pc.h":"Node Core for Windows and Linux","mining.pc.p":"A full node, a wallet and a miner in one program. Node Core checks every block itself and mines with your processor and with graphics cards from NVIDIA, AMD and Intel. Version 1.1.0, for Windows 10 and 11 and for 64-bit Linux.","mining.pc.s1":"Download the installer and run it.","mining.pc.s2":"Create a wallet and write down the 12 words, or bring your wallet over with them.","mining.pc.s3":"Under Mining, choose solo or a pool, pick processor or graphics card, and start.","mining.pc.win":"Download for Windows","mining.pc.deb":"Download for Linux (.deb)","mining.pc.more":"Also available: an <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/download/node-core-v1.1.0/YSKAR-Node-Core-1.1.0-x86_64.AppImage' target='_blank' rel='noopener'>AppImage</a> for other Linux distributions, and the <a class='ext' href='https://github.com/dabitlex/YSKAR/releases/tag/node-core-v1.1.0' target='_blank' rel='noopener'>release notes with checksums</a>.","mining.pc.note":"<strong>The Windows installer is not signed.</strong> Windows therefore asks once: choose “More info”, then “Run anyway”. Compare the checksum with the release notes if you want to be sure the file is the published one.","mining.pc.imgcap":"Node Core, overview. The figures in the picture are examples.","mining.phone.h":"On your phone","mining.phone.p":"The easiest way to get to know YSKAR. A phone contributes little hash power and finds blocks only in a pool. Serious mining runs on PCs and rigs.","mining.phone.s1":"Install the Android app from GitHub, or open the Mini App in Telegram.","mining.phone.s2":"Create a wallet and write down the 12 words on paper.","mining.phone.s3":"Choose a pool and start mining.","mining.phone.apk":"Android app with mining","mining.phone.tg":"Mini App in Telegram","mining.phone.f1":"Android app","mining.phone.f1.v":"Keeps mining in the background, also with the screen locked, and shows the status in a home-screen widget. Distributed as an APK, because app stores do not allow on-device mining.","mining.phone.f2":"Mini App","mining.phone.f2.v":"Nothing to install. Runs inside Telegram while it is open. Your coins depend on your 12 words, not on your Telegram account.","mining.phone.f3":"YSKAR Wallet","mining.phone.f3.v":"The wallet app does not mine. It is made for sending, receiving and signing.","mining.cli.h":"The command-line miner","mining.cli.p":"For Windows, macOS and Linux. The miner needs only an address: no key, no wallet and no sign-up. You can run it on a computer you do not control.","mining.cli.f1":"Needs","mining.cli.f1.v":"Node.js 20 or newer, nothing else to install","mining.cli.f2":"Graphics cards","mining.cli.f2.v":"add <code>--gpu</code>. It uses <code>yskar-cuda</code> for NVIDIA and <code>yskar-opencl</code> for AMD and Intel","mining.cli.f3":"Solo","mining.cli.f3.v":"mine against your own full node and leave out <code>--mode pool</code>","mining.cli.link":"The full guide to the miner","mining.cli.c1":"get the miner and test this computer","mining.cli.c2":"mine in the public pool","mining.cli.c3":"or solo, against your own node","mining.cli.addr":"Replace <code>ysr1...</code> with your own address. Rewards go straight to it.","mining.rig.h":"Mining rigs with HiveOS","mining.rig.p":"A ready package for HiveOS: the command-line miner with the GPU programs, one miner per graphics card.","mining.rig.dl":"Download the package 1.1.0","mining.rig.doc":"Flight sheet and setup","mining.rig.f1":"Cards","mining.rig.f1.v":"NVIDIA (CUDA), AMD and Intel (OpenCL)","mining.rig.f2":"Fee","mining.rig.f2.v":"none in the miner. A pool keeps its own fee","mining.rig.f3":"Setup","mining.rig.f3.v":"your address and the pool go into the flight sheet. The guide shows every field","mining.return":"<strong>Nobody can promise you a return.</strong> How often you receive something depends on your hash power, on the power of the whole network and on chance. YSR has no market price.","pools.p1":"Solo, you search alone and keep the whole reward of a block you find. In a pool, many search together and the reward is split by the work each one delivered.","pools.p2":"A YSKAR pool is not a service with accounts. It is a node whose blocks pay every miner directly, in the block itself. The operator never holds anyone else's coins, and there is no payout threshold.","pools.reported":"{r} reported","pools.c5":"Of the last {n}","pools.full":"full","pools.cap":"Miners, seats and hashrate are what each pool reports about itself. The share of the last {n} blocks is counted from the chain.","pools.f1":"Accounting","pools.f1.v":"By the shares of the recent past (PPLNS). If you have only just started, your part of the first block is small.","pools.f2":"Seats","pools.f2.v":"A block can pay at most 64 addresses, so a pool has 63 seats plus the operator's fee. From revision 6 it is 254.","pools.f3":"Fee","pools.f3.v":"Set by the operator, between 0 and 5 %.","pools.f4":"Your own pool","pools.f4.v":"Any node can be a pool, without registration. <a class='ext' href='https://github.com/dabitlex/YSKAR/blob/main/docs/POOL.md' target='_blank' rel='noopener'>How to run one</a>","calc.p":"Enter your hashrate. The estimate uses the work in the latest blocks of the chain, not the figures pools report about themselves. Node Core and the miner show your hashrate while they run.","calc.unit":"Unit","calc.mode":"How you mine","calc.pool":"In a pool","calc.solo":"Solo","calc.which":"Pool","calc.day":"Per day, on average","calc.week":"Per 7 days","calc.month":"Per 30 days","calc.share":"Your share of the network","calc.d.every":"One block on average every","calc.d.chance":"Chance of at least one block in 24 hours","calc.d.block":"Per block you find","calc.d.poolEvery":"The pool finds a block about every","calc.d.part":"Your part of each pool block","calc.d.fee":"Pool fee, already deducted","calc.d.poolShare":"Pool's share of the last {n} blocks","calc.d.net":"Network hashrate from the last {n} blocks","calc.enter":"Enter a hashrate above 0.","calc.note":"An estimate, not a promise. Blocks are found by chance, and the difficulty follows the whole network. Fees are not included.","calc.halving":"The halving at block {b} is in about {d} days. The 7-day and 30-day figures already count half the reward after it.","calc.every.min":"{n} minutes","calc.every.hours":"{n} hours","calc.every.days":"{n} days","calc.every.years":"{n} years","net.hashrate":"Network hashrate","net.difficulty":"Difficulty","net.now":"Right now","net.height":"Block height","net.fromChain":"work of the last 24 blocks, divided by their time","net.everyBlock":"recomputed for every block","net.blocktime":"Block time, last 50 blocks","net.target600":"target: 600 s","net.mempool":"Transfers waiting","net.fromNode":"at the main node","net.miners":"Active miners","net.sessions":"Mining sessions","net.nodes":"Nodes reporting","net.reported":"reported, not verifiable","net.next.v6":"Revision 6 at block 10,000","net.next.halving":"First halving at block 12,000","net.hist.h":"History, read from the blocks","net.hist.p":"Every block of the chain, summed by day in UTC. The history is complete up to block <span data-live='snapTip'></span>; the figures above are read live.","net.range":"Period","net.range.all":"Since block 0","net.range.30":"30 days","net.range.7":"7 days","net.c.hash":"Hashrate per day","net.c.hash.capLog":"Work of the day's blocks divided by their time. Logarithmic scale: each line is ten times the one below.","net.c.hash.capLin":"Work of the day's blocks divided by their time.","net.c.blocks":"Blocks per day","net.c.blocks.cap":"Complete days only. At the target block time a day has 144 blocks.","net.c.blocks.ref":"Target: 144 blocks per day","net.c.blocks.name":"blocks","net.c.finders":"Blocks per day, by finder","net.c.finders.cap":"Complete days only. Pool blocks carry the pool's name in the chain; a block that pays a single address counts as solo.","net.c.time":"Average block time per day","net.c.time.cap":"Seconds between blocks, averaged over the day.","net.c.time.ref":"Target: 600 seconds","net.c.day":"Day (UTC)","net.s.main":"YSKAR MAIN","net.s.gozero":"Gozero","net.s.solo":"Solo","net.find.h":"Who finds the blocks","net.find.p1":"In the first weeks every block was found solo. Today nearly all blocks come from two pools, and most of them from one.","net.find.p2":"This matters. A pool's operator chooses the transactions and the parent of every block the pool works on, and whoever directs most of the hash power can build the chain with the most work. More pools and more solo miners make the chain harder to steer.","net.find.link":"The pools, and how to run your own","net.find.title":"Share of blocks found","net.find.last":"Last {n} blocks","net.find.last1000":"The 1,000 blocks up to block {h}","net.find.allb":"All blocks up to block {h}","net.find.cap":"Counted from the chain. The first bar follows the live chain, the other two end where the embedded history ends.","net.blocks.h":"The latest blocks","net.blocks.p":"Select a block to see its header, recompute its proof of work and read its transactions.","net.blocks.link":"Open the explorer","net.blocks.title":"Newest first","net.b.height":"Height","net.b.age":"Found","net.b.by":"By","net.b.paid":"Paid to","net.b.diff":"Difficulty","net.b.solo":"solo","net.b.addr":"{n} addresses","net.b.addr1":"1 address","net.src.h":"Where the numbers come from","net.src.p":"Not every figure on this page has the same weight.","net.src.1.h":"From the chain","net.src.1.p":"Height, difficulty, supply and every chart on this page. The hashrate is the work in the latest blocks divided by the time they took. Anyone who runs a full node can recompute all of it.","net.src.2.h":"Reported","net.src.2.p":"Active miners, sessions, nodes and the hashrate a pool states about itself. These are self-reports. They show a direction, and nobody can check them.","net.src.3.h":"The mirror","net.src.3.p":"This page and the explorer read a database copy of the chain, so that they load quickly. The mirror checks every block it stores, but it is a convenience. The chain is what the full nodes agree on.","net.src.4.h":"Seed nodes","net.src.4.p":"A new node first contacts <code>pool.yskar.app:8646</code> or <code>yskar-seed2.dynv6.net:8646</code>. Both are run by the same operator. After that, nodes exchange the addresses of other nodes among themselves.","ex.q.label":"Search the chain","ex.q.go":"Search","ex.try":"Places to start:","ex.try.0":"block 0","ex.try.burn":"the burn in block 3,974","ex.try.or":"or","ex.try.zero":"the address nobody can spend from","ex.crumb":"Explorer","ex.msg.empty":"Enter a block height, a block hash, a transaction ID or an address.","ex.msg.badAddr":"This address has a typo: its checksum does not match. Check it character by character.","ex.msg.addrShape":"This is not a YSKAR address. Addresses start with ysr1 and have 42 characters.","ex.msg.tooHigh":"Block {h} does not exist yet. The chain is at block {tip}.","ex.msg.notFound":"Nothing on the chain matches this.","ex.msg.offlineHash":"The chain is not answering right now, so this hash cannot be looked up. Try again in a moment.","ex.msg.searching":"Searching the chain.","ex.msg.badLink":"This link does not point to a block, a transaction or an address.","ex.loading":"Reading from the chain.","ex.missing.h":"The chain is not answering right now","ex.missing.p":"The explorer reads every block, transfer and address from the public YSKAR API, and that request just failed. It tries again on its own as soon as the chain answers.","ex.missing.link":"Try again now","ex.none.block":"The chain has no block {h}. It is at block {tip}.","ex.none.tx":"No transaction with this ID is known: it is in no block and not waiting for one. If you sent it a moment ago, this page looks again on its own.","ex.back":"Back to the latest blocks","ex.latest.h":"Latest blocks","ex.latest.snap":"The chain is not answering right now. These are the latest {n} blocks as of the last answer.","ex.latest.live":"Read from the public API and refreshed every 45 seconds.","ex.older":"Show older blocks","ex.older.busy":"Reading","ex.c.height":"Height","ex.c.found":"Found","ex.c.by":"By","ex.c.transfers":"Transfers","ex.c.size":"Size","ex.c.hash":"Block hash","ex.solo":"Solo miner","ex.bytes":"{n} bytes","ex.block.h":"Block {h}","ex.prev":"Previous block","ex.next":"Next block","ex.block.sumPool":"Found on {date}, {ago}, by the pool {who}.","ex.block.sumSolo":"Found on {date}, {ago}, by a solo miner.","ex.block.sumGenesis":"The first block of the chain, dated {date}. Its reward went to an address nobody can spend from.","ex.block.partial":"The chain is not answering right now. This is the header of the block as the page already had it, so you can still check its proof of work. Its transactions follow as soon as the chain answers.","ex.block.values":"What the header says","ex.block.values.p":"These values are packed into the 136 bytes above. Change one of them and the hash no longer fits.","ex.f.hash":"Block hash","ex.f.prev":"Previous block","ex.f.prev.none":"None. This is the first block.","ex.f.merkle":"Merkle root","ex.f.merkle.s":"Fingerprint of the transactions in this block","ex.f.state":"State root","ex.f.state.s":"Fingerprint of every balance after this block","ex.f.diff":"Difficulty","ex.f.diff.s":"About {n} attempts were needed on average","ex.f.nonce":"Nonce and extranonce","ex.f.nonce.s":"The two counters the miner turned until the hash fit","ex.f.size":"Size","ex.f.size.v":"{n} bytes with {tx} transactions","ex.f.size.v1":"{n} bytes with 1 transaction","ex.txs.h":"Transactions in this block","ex.txs.p":"The first one creates the block reward. Every other one is a transfer signed by its sender.","ex.tx.coinbase":"Block reward","ex.tx.transfer":"Transfer","ex.tx.other":"Transaction of type {type}","ex.tx.new":"{a} newly created","ex.tx.newFees":"{a} newly created and {f} in fees","ex.tx.from":"From","ex.tx.to":"To","ex.tx.amount":"Amount","ex.tx.fee":"Fee","ex.tx.memo":"Note","ex.tx.memoHex":"Note (bytes)","ex.tx.nonce":"Sender's counter","ex.tx.nonce.s":"Each transfer of an address carries the next number, so none can be replayed","ex.tx.id":"Transaction ID","ex.tx.paid":"Paid in the block itself to {n} addresses. The pool never held these coins.","ex.tx.c.addr":"Address","ex.tx.c.amount":"Amount in YSR","ex.tx.c.share":"Share","ex.unspendable":"unspendable","ex.txv.sum":"Confirmed in block {h} on {date}.","ex.txv.block":"Block","ex.txv.until":"Valid until","ex.txv.until.none":"No expiry set","ex.txv.until.h":"Block {h}","ex.txv.size":"Size","ex.txv.raw":"The bytes as they stand in the block","ex.txv.raw.p":"A node checks exactly these bytes: the signature, the sender's balance and the counter.","ex.txv.how":"How a transfer is built","ex.addr.h":"Address","ex.addr.zero":"Nobody holds a key for this address. Whatever arrives here can never be spent again.","ex.addr.balance":"Balance","ex.addr.sent":"Transfers sent","ex.addr.first":"First seen","ex.addr.last":"Last active","ex.addr.blockN":"Block {h}","ex.addr.solo":"Block rewards received","ex.addr.pool":"Pool payouts received","ex.addr.hist":"Latest activity","ex.addr.more":"The latest {n} entries.","ex.addr.none":"The chain has no entry for this address yet. An address is valid as soon as its key exists; the chain learns about it with the first payment.","ex.h.block":"Block","ex.h.when":"When","ex.h.what":"What","ex.h.with":"With","ex.h.amount":"Amount","ex.h.fee":"Fee","ex.k.in":"Received","ex.k.out":"Sent","ex.k.reward":"Block reward","ex.k.pool":"Pool payout","ex.copy.addr":"Copy address","ex.copy.id":"Copy ID","ex.block.sumPoolNoName":"Found on {date}, {ago}, by a pool.","dev.node.h":"Run a full node","dev.node.p":"A full node keeps its own copy of the chain and checks every block itself. It takes nothing on trust, not from other nodes and not from this website.","dev.node.link":"What a node checks in every block","dev.node.c1":"Get the source and build the node","dev.node.c2":"Start it: connect to the seed nodes, download the chain, check every block","dev.node.c3":"Mine against your own node, in a second terminal","dev.node.f1.k":"You need","dev.node.f1.v":"Node.js 22.13 or newer and Git. The node stores the chain with the SQLite module built into Node.js.","dev.node.f2.k":"Ports","dev.node.f2.v":"TCP 8646 for other nodes, 8645 for the HTTP interface that miners and wallets use.","dev.node.f3.k":"Clock","dev.node.f3.v":"Keep the system clock correct. A block dated more than 120 seconds ahead of your node's clock is rejected.","dev.node.f4.k":"Seed nodes","dev.node.f4.v":"The command-line node has no seed built in. Name both seed nodes, as in the command above.","dev.node.f5.k":"<code>--no-upstream</code>","dev.node.f5.v":"Belongs in the command. Without it the node would also exchange blocks with the project's database mirror, which only accepts blocks from the main node.","dev.node.core":"On Windows, type <code>npm.cmd</code> in place of <code>npm</code> in PowerShell. If you prefer a window to a terminal, <a href=\"/node#core\">Node Core</a> runs the same full node on Windows and Linux.","dev.api.h":"Read the chain over HTTP","dev.api.p":"The public API answers plain GET requests with JSON. Pick a request and read the answer.","dev.api.title":"API console","dev.api.pick":"Requests","dev.api.out":"Answer","dev.api.run":"Send again","dev.api.curl":"Copy as curl","dev.api.busy":"Waiting for the answer.","dev.api.ok":"{status} in {ms} ms, answered live by www.yskar.app.","dev.api.fail":"The request failed ({why}). Showing the last answer this page received, from {date}.","dev.api.e.summary":"Height, difficulty, hashrate, supply","dev.api.e.blocks":"The latest blocks, newest first","dev.api.e.block":"One block with all its transactions","dev.api.e.tx":"One transaction by its ID","dev.api.e.account":"Balance and history of an address","dev.api.e.search":"What kind of thing is this text?","dev.api.e.fees":"The fee a transfer needs right now","dev.api.e.pools":"The pools and their reported figures","dev.api.e.supply":"Minted, unspendable and circulating","dev.api.e.circ":"The circulating supply as a plain number","dev.api.n1.h":"Read-only and open","dev.api.n1.p":"No key and no account. Cross-origin requests are allowed, so a web page can call the API directly.","dev.api.n2.h":"Your own node answers too","dev.api.n2.p":"Every full node serves the same read routes on port 8645. Point your code at <code>http://127.0.0.1:8645</code> and you depend on nobody's server.","dev.api.n3.h":"Amounts are whole numbers","dev.api.n3.p":"Amounts come in units: 1 YSR is 100,000,000 units. Read them as integers or strings and never as floating-point numbers.","dev.docs.h":"The documents","dev.docs.p":"Written for people who want to check the claims. Each one links to the code it describes.","dev.docs.v6":"The binding specification of revision 6, active from block 10,000.","dev.docs.fullnode":"The command-line full node: commands, options, HTTP interface, storage and reorganizations.","dev.docs.p2p":"The protocol nodes speak with each other.","dev.docs.fees":"The fee rules and how the fee estimate is made.","dev.docs.pool":"Pools: joining one, running one, how the accounting works.","dev.docs.ops":"The public infrastructure: main node, HTTPS, mirror and its settings.","dev.repo.h":"What is where","dev.repo.p":"One repository holds the consensus code, the node, the miner and the tests that guard them.","dev.repo.core":"Consensus: header, difficulty, transactions, state, wallet derivation","dev.repo.fullnode":"Full node: chain, mempool, mining interface, read API, command line","dev.repo.p2p":"The node-to-node protocol","dev.repo.pool":"PPLNS accounting and the split of the block reward","dev.repo.node":"Build of the command-line full node","dev.repo.nodecore":"Node Core for Windows and Linux, with the GPU miners","dev.repo.miner":"The command-line miner, without dependencies","dev.repo.observer":"The observer: a small read-only tool that downloads the chain and recomputes every block","dev.repo.tests":"Tests of consensus, node, P2P, pool and wallet","dev.repo.docs":"The documentation listed above","dev.repo.c1":"From the repository root: install, run the tests, check the types","dev.sign.h":"Signed messages","dev.sign.p":"A wallet can prove that it controls an address without moving a coin. All YSKAR software signs and checks the same text format.","dev.sign.1":"The signature is Ed25519 over the raw UTF-8 bytes of the whole message, checked by the same rule as on the chain.","dev.sign.2":"The first line makes it safe: a transaction is binary and never starts with these words, so a signed message can never count as a transfer.","dev.sign.3":"YSKAR Wallet and Node Core sign such messages. YSKAR Lab uses them to sign you in without a password.","dev.con.h":"Contribute and report","dev.con.1.h":"Changes to the code","dev.con.1.p":"<a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/blob/main/CONTRIBUTING.md\" target=\"_blank\" rel=\"noopener\">CONTRIBUTING.md</a> says which checks must pass before a push: the type checks and the full test suite.","dev.con.2.h":"Ideas and proposals","dev.con.2.p":"Proposals for the protocol and the software are discussed in the open at <a class=\"ext\" href=\"https://lab.yskar.app\" target=\"_blank\" rel=\"noopener\">YSKAR Lab</a>. You sign in with your wallet.","dev.con.3.h":"Security problems","dev.con.3.p":"Report them as an issue at <a class=\"ext\" href=\"https://github.com/dabitlex/YSKAR/issues\" target=\"_blank\" rel=\"noopener\">github.com/dabitlex/YSKAR/issues</a>. Issues are public: describe what you saw and how to reproduce it, and never post your 12 words, a PIN, a wallet file or a key.","ysr.now.blocks":"blocks","ysr.bar.circ":"In circulation","ysr.bar.burned":"Burned","ysr.bar.open":"Not yet issued","ysr.bar.cap":"Shares of the 21,000,000 YSR that can ever exist.","ysr.sched.title":"Issuance by block height","ysr.sched.series":"issued","ysr.sched.when.past":"already mined","ysr.sched.when.future":"around {date}, at 600 s per block","ysr.t.all":"Show all 37 eras","ysr.t.less":"Show the first 8 eras","ysr.t.now":"now","ysr.fees.h":"Fees","ysr.fees.p":"A transfer pays a fee to the miners of the block that includes it. The rules set only a floor. Above it, the price follows the demand for space in a block.","ysr.fees.f1":"Floor by consensus","ysr.fees.f1.v":"1 unit per byte","ysr.fees.f2":"Floor to be relayed","ysr.fees.f2.v":"10 units per byte. This is a setting of the nodes, not a consensus rule.","ysr.fees.f3":"A plain transfer of 168 bytes","ysr.fees.f3.v":"at least, right now","ysr.fees.f4":"Slow, normal, fast","ysr.fees.f4.v":"The three tiers only differ when blocks are full. Otherwise the minimum fee is enough for the next block.","ysr.fees.f5":"Smallest amount","ysr.fees.f5.v":"100 units, which is 0.000001 YSR","ysr.fees.f6":"Transfers waiting for a block","ysr.noprice.h":"No price, no promise","ysr.noprice.p1":"YSR has no price and no market, and it is not listed on any exchange. Nothing on this site promises that this will change, and nobody should mine in that expectation.","ysr.noprice.p2":"What YSR has is a set of rules that anyone can check: a fixed maximum, a public issuance schedule, and coins that only their owner's key can move.","tech.header.h":"A block starts with 136 bytes","tech.header.p1":"The header names the block before it, commits to every transaction and to every balance after the block, and carries the nonce the miner found. The block hash is SHA-256, applied twice, over exactly these bytes.","tech.header.p2":"The length is chosen on purpose. SHA-256 works in blocks of 64 bytes, and everything except the nonce lies in the first 128. A miner computes that part once per job; every further attempt costs two compression steps.","tech.pow.h":"Work that anyone can check","tech.pow.p1":"A block is valid only if its hash, read as a number, is not larger than a target. The target follows from the difficulty. There is no shortcut: the only way to find such a hash is to try nonces, and checking the result takes two hash computations.","tech.pow.p2":"One unit of difficulty stands for 65,536 expected attempts. At the current difficulty of <span class='mono' data-live='difficulty'></span>, the network needs about <span data-live='attempts'></span> attempts for one block.","tech.diff.h":"The difficulty follows the network","tech.diff.p1":"The difficulty is recomputed for every block from the last 45 blocks. Recent blocks count more than older ones, so the chain reacts quickly when hash power arrives or leaves.","tech.diff.p2":"Every node computes the same range from the same blocks and rejects a block that states a difficulty outside it. Only whole numbers are used, so two nodes can never round differently.","tech.diff.chart":"Difficulty since block 1","tech.diff.cap":"Mean of every 24 blocks up to block <span data-live='snapTip'></span>. The scale is logarithmic: each line is ten times the one below.","tech.diff.f1":"Window","tech.diff.f1.v":"the last 45 blocks, the newest weighted highest","tech.diff.f2":"Largest step","tech.diff.f2.v":"a factor of 4 up or down per block","tech.diff.f3":"Solve time counted","tech.diff.f3.v":"1 to 3,600 seconds per block","tech.diff.f4":"Emergency rule","tech.diff.f4.v":"after 1,800 seconds without a block, the requirement falls in proportion to the waiting time","tech.diff.f5":"Timestamps","tech.diff.f5.v":"later than the median of the last 11 blocks, at most 120 seconds ahead of the node's clock","tech.acc.h":"Accounts and transfers","tech.acc.p1":"YSKAR keeps one balance and one nonce per address. A transfer names sender, recipient, amount and fee, and is signed with the sender's key. Without that key nobody can move the coins.","tech.acc.p2":"The state root in every header commits to all balances. A node that replays the chain from block 0 arrives at the same balances as every other node, or it rejects the block.","tech.tx.title":"A transfer, 168 bytes","tech.tx.p":"Plus an optional note of up to 32 bytes. Sizes in bytes.","tech.tx.aria":"The fields of a transfer and their sizes in bytes","tech.tx.f1":"Version and type","tech.tx.f2":"Sender address","tech.tx.f3":"Recipient address","tech.tx.f4":"Amount","tech.tx.f5":"Fee","tech.tx.f6":"Sender's nonce","tech.tx.f7":"Expiry height and note length","tech.tx.f8":"Public key","tech.tx.f9":"Signature","tech.acc.f1":"Valid once","tech.acc.f1.v":"The nonce must equal the number of transfers the sender has made so far, so the same transfer can never be applied twice.","tech.acc.f2":"Tied to this network","tech.acc.f2.v":"The signature covers the chain ID. A transfer signed for YSKAR is invalid anywhere else.","tech.acc.f3":"Expiry","tech.acc.f3.v":"A sender can name a last block height. After it, the transfer can never be included.","tech.acc.f4":"Note","tech.acc.f4.v":"Up to 32 bytes, stored publicly in the chain.","tech.acc.f5":"Minimum fee","tech.acc.f5.v":"1 unit per byte by consensus. Nodes relay from 10 units per byte. Fees go to the miners of the block.","tech.acc.f6":"A plain transfer costs","tech.acc.f6.v":"right now at least","tech.key.aria":"From 12 words to an address","tech.key.1":"Seed words","tech.key.2":"Derivation path","tech.key.3":"Key pair","tech.key.4":"Address","tech.key.p":"A wallet is 12 or 24 words (BIP39). The key is derived from them on the device (SLIP-0010), and the address is the first 20 bytes of the SHA-256 hash of the public key, written in bech32m. The words never leave the device that created them.","tech.nodes.h":"Every node checks every block","tech.nodes.p1":"A full node stores the whole chain and accepts a block only after it has checked it completely, whether the block comes from another node or from its own miner. The checks run in this order.","tech.nodes.link":"Run a full node","tech.check.1":"Version, at most 2,000 transactions, exactly one reward transaction in first place, and the transaction root.","tech.check.2":"The hash of the header, applied twice, is not larger than the target of the stated difficulty.","tech.check.3":"The height is the parent's height plus one, and the previous hash is the hash of the parent.","tech.check.4":"Later than the median of the last 11 blocks, not before the parent, and at most 120 seconds ahead of the node's clock.","tech.check.5":"The stated difficulty lies in the range that follows from the previous blocks.","tech.check.6":"Signature, sender, nonce, balance, fee and expiry of every transfer. The reward transaction pays exactly the block reward plus the fees.","tech.check.7":"The root over all accounts after the block equals the state root in the header.","tech.nodes.chain.h":"Which chain counts","tech.nodes.chain.p":"The valid chain with the most accumulated work, where the work of a block is its difficulty. A node keeps competing blocks and switches when another branch has more work.","tech.nodes.pool.h":"Pools without custody","tech.nodes.pool.p":"The reward transaction of a block may pay up to 64 addresses. A pool's accounting becomes that transaction, so the chain pays every miner directly and the operator never holds anyone else's coins. <a href='/mining#pools'>How pools work</a>","tech.rev.h":"Rules change at a block height","tech.rev.p":"A rule change is written into the code together with the height at which it starts. Every node switches at the same block, and every block below that height keeps its rules, byte for byte.","tech.rev.c1":"Revision","tech.rev.c2":"From block","tech.rev.c3":"Change","tech.rev.c4":"Status","tech.rev.2":"The reward transaction may pay several addresses. Pools are built on this.","tech.rev.3":"A minimum fee per byte replaces the fixed fee, and a smallest amount applies.","tech.rev.4":"The difficulty field can hold values of any size.","tech.rev.5":"Stricter rules for timestamps, block encoding and the reward transaction.","tech.rev.6":"Shared accounts, time and hash locks, batch payments, a new state tree and higher limits.","tech.rev.note":"Revisions 2 to 5 corrected and tightened rules. Revision 6 is the first that adds capabilities, and the first that older nodes cannot follow.","tech.v6.h":"Revision 6","tech.v6.p":"The next rule change starts at block 10,000. The community chose that height in a vote on 25 October 2026. It changes the account record, the address format and the transaction format, so that accounts can do more than hold a balance.","tech.v6.count":"Block 10,000","tech.v6.spec":"Read the specification of revision 6","tech.v6.1.h":"Shared accounts","tech.v6.1.p":"Accounts that need several signatures to spend, for example 2 of 3, with up to 16 keys. For shared funds and safer savings.","tech.v6.2.h":"Time locks","tech.v6.2.p":"YSR that can only be spent from a chosen block height on.","tech.v6.3.h":"Hash locks","tech.v6.3.p":"A payment is released only against a secret, and returns to the sender after a set height. Two parties can trade without trusting each other.","tech.v6.4.h":"Batch payments","tech.v6.4.p":"One transaction pays up to 1,000 recipients at once.","tech.v6.5.h":"More room per block","tech.v6.5.p":"Up to 5,000 transactions per block instead of 2,000, and a pool's block can pay up to 255 addresses instead of 64.","tech.v6.6.h":"A foundation for later","tech.v6.6.p":"A state tree built for many thousands of accounts, addresses with a version, and a fork identifier in every signature.","tech.v6.same.h":"What stays the same","tech.v6.same.1":"21 million YSR and the halving schedule","tech.v6.same.2":"10-minute blocks, SHA-256 and the difficulty rules","tech.v6.same.3":"Every address, every key and every balance","tech.v6.do.h":"What you need to do","tech.v6.do.1":"Update your wallet and your node before block 10,000","tech.v6.do.2":"Miners, the GPU miners and the HiveOS package need no update","tech.v6.do.3":"An outdated wallet still receives YSR. It cannot send until it is updated","tech.lim.h":"Known limits","tech.lim.p":"What the system does not protect against today. The list comes from the project's own security document.","tech.lim.link":"The full security model","tech.lim.1.h":"A small network","tech.lim.1.p":"The network has two seed nodes, both run by the same operator. Proof of work protects a chain only as long as no single party controls most of the hash power, and hash power that mines through one pool is directed by that pool's operator.","tech.lim.2.h":"No checkpoints","tech.lim.2.p":"A node switches to any valid chain with more work, however far back it forks. Treat a transfer as more final the more blocks are built on top of it.","tech.lim.3.h":"The explorer's data source","tech.lim.3.p":"Explorer and apps read from a mirror, a database copy of the chain kept for speed. It is a convenience, not the authority: the chain is what the full nodes agree on.","tech.lim.4.h":"Pool seats","tech.lim.4.p":"A pool has at most 64 seats, 63 if it charges a fee; from revision 6 it is 255 and 254. Opening a session needs only a valid address, so seats can be occupied cheaply.","tech.lim.5.h":"Open interfaces","tech.lim.5.p":"A node's HTTP interface does not limit requests per client. On a public node, a reverse proxy has to do that.","tech.docs.1":"The protocol specification: formats, hashing, difficulty, validity rules and test vectors.","tech.docs.3":"What cryptography and consensus enforce, what you have to trust, and the known limits.","miner.title":"Search for a nonce yourself","miner.state":"Runs in your browser","miner.intro":"Your browser takes the header of the latest block and tries nonces against an easier target. The real target is far beyond what a browser can reach.","miner.bits":"Zero bits the hash must start with","miner.odds":"{b} bits: about 1 hash in {n}","miner.start":"Start the search","miner.stop":"Stop","miner.attempts":"Attempts","miner.speed":"Speed","miner.time":"Time","miner.nonce":"Nonce found","miner.hash":"Last hash tried","miner.hashFound":"Hash found","miner.target":"Target of this demo","miner.found":"Found after {n} attempts.","miner.none":"No hash below the target in {n} attempts. Start again, or ask for fewer zero bits.","miner.stopped":"Stopped after {n} attempts.","miner.real":"At {r}, this browser would need about {t} on average to find a real block at today's difficulty.","field.version":"Version","field.version.d":"The version of the header. It is 1 today and becomes 6 with consensus revision 6.","field.height":"Height","field.height.d":"The number of this block, counted from block 0.","field.prev":"Previous hash","field.prev.d":"The hash of the block before. It chains the blocks: changing an old block would change every hash after it.","field.merkle":"Transaction root","field.merkle.d":"One hash over all transactions in the block. A single changed byte in any of them changes it.","field.state":"State root","field.state.d":"One hash over every balance and nonce after this block. Each node computes it itself and compares.","field.time":"Timestamp","field.time.d":"When the miner built the block. It must be later than the median of the last 11 blocks.","field.diff":"Difficulty","field.diff.d":"How hard this block had to be. The target follows from it: 2^240 divided by the difficulty.","field.count":"Transaction count","field.count.d":"How many transactions the block holds, including the one that pays the reward.","field.extra":"Extranonce","field.extra.d":"A value the node gives each miner, so that two miners never search the same headers.","field.nonce":"Nonce","field.nonce.d":"The number the miner varied until the hash fell below the target. Nothing else changes between two attempts.","proof.fixedBlock":"Fixed in the chain","proof.block":"Block {h}","proof.found":"found {ago}","proof.fixed":"Unchanged since 9 Sep 2026","proof.cap":"The block header: 136 bytes in ten fields.","proof.bytesLabel":"The 136 bytes of the header of block {h}, in hexadecimal","proof.range":"bytes {a} to {b}","proof.first":"SHA-256 of the 136 bytes","proof.hash":"SHA-256, applied twice: the block hash","proof.target":"Target at difficulty {d}","proof.valid":"Valid. The hash is below the target.","proof.invalid":"Not valid. The hash is above the target.","proof.time":"Computed in your browser in {ms} ms.","proof.again":"Check again","proof.genesis":"Check block 0","proof.latest":"Check the latest block","proof.open":"Open this block in the explorer","check.1":"Structure","check.2":"Proof of work","check.3":"Place in the chain","check.4":"Timestamp","check.5":"Difficulty","check.6":"Every transaction","check.7":"State root","chart.asTable":"Show the values as a table","chart.total":"total","chart.height":"Up to block","n.2000":"2,000","n.4000":"4,000","n.6000":"6,000","n.7000":"7,000","n.10000":"10,000","rev.active":"active since {date}","rev.set":"set, {n} blocks to go","ms.done":"active","home.how.1.h":"Miners search","home.how.1.p":"Phones, PCs and graphics cards hash a block header over and over, each time with a different nonce. A hash below the target makes the block valid.","home.how.2.h":"Nodes check","home.how.2.p":"Every full node recomputes the work, the signatures and all balances, starting at block 0. A block that breaks a rule is rejected, whoever sent it.","home.how.3.h":"The block pays","home.how.3.p":"The block itself pays the reward: to the finder alone, or split among the miners of a pool, straight to their addresses. A pool never holds anyone else's coins.","dev.api.down":"The request failed ({why}). The API is not answering from here right now."};window.YSKAR_TEXTE_DA&&window.YSKAR_TEXTE_DA("en");
